function emergency_move_1942() {
    G.active = AP
    var unit_to_retreat = []
    for_each_unit_on_map((u, piece, location) => {
        if (piece.faction === AP && piece.class === "naval" && location !== OAHU) {
            set_add(unit_to_retreat, u)
        }
    })
    call("emergency_move", {unit_to_retreat})
}

