                philippinesKeysRequired: nations.PHILIPPINES.keys.length,
                deiKeysHeld: nations.DEI.keys.filter(k => is_space_controlled(hex_to_int(k), JP)).length,
                deiKeysRequired: nations.DEI.keys.length,
